main_mermaid = '''flowchart TD
  D[Demand: process, actions, MTM, layout, demand, people, costs]
  S[Supply: products, configurations, capabilities, performance evidence, prices]
  D --> B[Check the baseline and action requirements]
  S --> C[Check configuration limits and evidence]
  B --> M[Match actions to products: supported, blocked, unknown]
  C --> M
  M --> H[Design options: current method, improved manual work, hybrid teams]
  M --> E[Close evidence gaps: benchmark, simulation, or field test]
  E --> C
  H --> P[Evaluate the whole process and fleet: people, handoffs, charge, failures, peaks]
  P --> F[Calculate cost, cash savings, payback, and sensitivity]
  F --> R[Compare options and recommend: proceed, test, change, defer, or stop]
  R --> A{Owner decision}
  A -->|Revise or collect data| D
  A -->|Proceed| L[Prepare deployment: configure or train as required, test, pilot]
  A -->|Defer or stop| X[Retain the case and reason]
  L --> O[Operate: measure output, cost, failures, and human work]
  O --> I[Improve the process, model, configuration, and business case]
  I --> B
  I --> C
'''
deployment_mermaid = '''flowchart TD
  A[Selected scenario and recorded decision] --> P[Plan site, interfaces, resources, tests, and support]
  P --> R{Which execution route is required?}
  R --> C[Configure OEM software, tools, and workflow]
  R --> T[Prepare data and adapt or train a policy/model]
  C --> V[Create a release record and test the supported configuration]
  T --> V
  V --> G{Ready for a supervised site pilot?}
  G -->|No| P
  G -->|Yes| H[Load and check supported hardware; run the supervised pilot]
  H --> M[Measure throughput, quality, interventions, cost, and remaining human work]
  M --> D{Review the result}
  D -->|Change| P
  D -->|Stop or roll back| S[Return to the agreed fallback]
  D -->|Accept| O[Operate and prepare scale-up]
  O --> M
'''

def svg_box(x,y,w,title,lines,kind="normal",h=112):
    colors={"normal":("#ffffff","#ccd8dc"),"input":("#e9f4f1","#87b6a5"),"decision":("#fff3d9","#d2ae54"),"external":("#edf0f8","#9caacc")}
    fill,stroke=colors[kind]
    body=f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="12" fill="{fill}" stroke="{stroke}" stroke-width="1.5"/>'
    body+=f'<text x="{x+18}" y="{y+28}" font-size="17" font-weight="700">{esc(title)}</text>'
    for index,line in enumerate(lines): body+=f'<text x="{x+18}" y="{y+53+index*20}" font-size="14">{esc(line)}</text>'
    return body

def arrow(path,label=None,lx=0,ly=0,dash=False):
    return f'<path d="{path}" fill="none" stroke="#5c797d" stroke-width="2" marker-end="url(#arrow)"'+(' stroke-dasharray="6 5"' if dash else '')+'/>'+(f'<text x="{lx}" y="{ly}" font-size="13" fill="#4d6266">{esc(label)}</text>' if label else '')

def main_svg():
    s=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1260 1135" role="img" aria-labelledby="title desc">', '<title id="title">Proposed application flow</title><desc id="desc">Demand and supply meet at action matching. Process and fleet evaluation feeds economics and a decision. Deployment and field results feed the next evaluation.</desc>', '<defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8" fill="#5c797d"/></marker></defs>', '<g font-family="Segoe UI,Arial,sans-serif" fill="#15343b">']
    boxes=[
    (30,30,360,"1. Define the demand",["Process, actions, timing, demand, layout,","engineering model, people, and cost"],"input"),
    (850,30,360,"2. Define the supply",["Products, complete configurations, limits,","performance evidence, and prices"],"input"),
    (30,205,360,"3. Check the human baseline",["Check actions, units, sources, and gaps.","Record skills and capability needs."],"normal"),
    (440,205,360,"5. Match actions and products",["Show supported, blocked, and unknown.","Check valid work bundles and conditions."],"normal"),
    (850,205,360,"4. Check the configuration",["Record hardware, tool, software, source,","test conditions, and missing evidence."],"normal"),
    (30,400,360,"6a. Keep alternative methods",["Current work, improved manual work,","assist tools, and other automation"],"normal"),
    (440,400,360,"6. Design the hybrid process",["Assign people and machines to actions.","Include handoffs and recovery work."],"normal"),
    (850,400,360,"6b. Close evidence gaps",["Request a benchmark, simulation, or trial.","The required evidence is an open choice."],"external"),
    (440,595,360,"7. Evaluate process and fleet",["Check robot counts, human time, charge,","failures, peaks, and the bottleneck."],"normal"),
    (30,595,360,"8. Calculate the business case",["Cost, staffing, retained cash benefit,","payback, and scenario stress tests"],"normal"),
    (30,790,360,"9. Compare and recommend",["Explain feasibility, economics, evidence,","gaps, and the next action."],"normal"),
    (440,790,360,"10. Record the owner decision",["Proceed, change, test, defer, or stop.","Keep the reviewed versions and reason."],"decision"),
    (850,790,360,"11. Prepare and run deployment",["Configure or train as required. Test.","Prepare hardware and a supervised pilot."],"external"),
    (850,985,360,"12. Operate and improve",["Compare expected and observed results.","Update evidence, process, and cost."],"input"),
    (30,985,360,"Retain the case",["Keep the reason for defer or stop.","Reopen when new evidence is available."],"normal"),
    ]
    paths=[("M210 142 V205",), ("M1030 142 V205",), ("M390 261 H440",), ("M850 261 H800",), ("M620 317 V400",), ("M390 456 H440",), ("M800 456 H850",), ("M1030 400 V317",), ("M620 512 V595",), ("M440 651 H390",), ("M210 707 V790",), ("M390 846 H440",), ("M800 846 H850","Proceed",797,832), ("M620 902 V950 H210 V985","Defer or stop",350,942), ("M1030 902 V985",), ("M620 790 V755 H14 V175 H210 V205","Revise or collect data",28,748,True), ("M1030 1097 H1238 V175 H1030 V205","Field evidence",1080,1121,True)]
    for a in paths: s.append(arrow(*a))
    for a in boxes:s.append(svg_box(*a))
    s.append('<text x="440" y="1050" font-size="15" font-weight="600">Dashed lines: review and learning loops</text>')
    s.append('<text x="440" y="1074" font-size="14">A case can stop or request more data.</text>')
    s.append('<text x="440" y="1097" font-size="14">A positive cost result does not prove readiness.</text>')
    return (''.join(s)+"</g></svg>").replace('id="title"','id="main-title"').replace('id="desc"','id="main-desc"').replace('aria-labelledby="title desc"','aria-labelledby="main-title main-desc"').replace('id="arrow"','id="main-arrow"').replace('url(#arrow)','url(#main-arrow)')

def deployment_svg():
    s=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1260 750" role="img" aria-labelledby="title desc"><title id="title">Deployment and improvement flow</title><desc id="desc">Plan the work. Use OEM configuration or a model training route as needed. Test the release and prepare the site. Run a supervised pilot, review measured results, then improve or scale.</desc><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8" fill="#5c797d"/></marker></defs><g font-family="Segoe UI,Arial,sans-serif" fill="#15343b">']
    boxes=[(30,30,360,"1. Plan deployment",["Selected process, configuration, team,","site changes, interfaces, and tests"],"normal"),
    (440,30,360,"2. Select the execution route",["AWS, OEM, and integrator define the route.","Use one or both paths below."],"decision"),
    (850,30,360,"3a. Configure the solution",["OEM software, tools, workflow, maps,","interfaces, and operating limits"],"normal"),
    (850,215,360,"3b. Adapt or train if required",["Data, labels, simulation assets, policy/model,","training runs, and failure tests"],"external"),
    (440,400,360,"4. Test the release and site",["Supported hardware and software version,","acceptance tests, fallback, and support"],"normal"),
    (30,400,360,"5. Review pilot readiness",["A person records the site decision.","Open issues can require a revised plan."],"decision"),
    (30,595,360,"6. Run the supervised pilot",["Load and check supported hardware.","Measure real process and cost results."],"external"),
    (440,595,360,"7. Review and improve",["Compare with the agreed baseline.","Change, stop, roll back, or accept."],"decision"),
    (850,595,360,"8. Operate and scale",["Track assets, releases, work, and benefit.","Check each new site before reuse."],"input")]
    for a in [("M390 86 H440",),("M800 86 H850",),("M800 113 H825 V271 H850",),("M1210 86 H1235 V370 H620 V400",),("M1030 327 V370 H620 V400",),("M440 456 H390",),("M210 512 V595",),("M390 651 H440",),("M800 651 H850",),("M620 595 V560 H14 V15 H210 V30","Revise and retest",32,553,True)]:s.append(arrow(*a))
    for a in boxes:s.append(svg_box(*a))
    s.append('<text x="30" y="740" font-size="14">Version 2 shows the full route. Real training, hardware loading, and physical robot control remain external integrations.</text>')
    return (''.join(s)+"</g></svg>").replace('id="title"','id="deployment-title"').replace('id="desc"','id="deployment-desc"').replace('aria-labelledby="title desc"','aria-labelledby="deployment-title deployment-desc"').replace('id="arrow"','id="deployment-arrow"').replace('url(#arrow)','url(#deployment-arrow)')

def table(headers,rows,classes=""):
    return '<div class="table-wrap"><table class="'+classes+'"><thead><tr>'+''.join('<th>'+esc(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'

def p(text):return '<p>'+esc(text)+'</p>'
def li(items):return '<ul>'+''.join('<li>'+esc(v)+'</li>' for v in items)+'</ul>'
def section(id,title,body):return f'<section id="{id}"><h2>{esc(title)}</h2>{body}</section>'

body=[]
body.append(section("mandate","1. Product goal and design rules",p("Help a site choose and deploy a better combination of people and technology. Start with the actual work. Match useful action bundles to supported products. Compare the complete process, its cost, and its evidence. Use measured site results to improve the next decision.")+p("This is a proposed design for validation. The current owner request takes priority over older prototype limits. Deployment belongs in the target platform, even where the mockup uses planning screens and external integration placeholders. The AWS proof of concept remains a bounded learning project.")+li([
"Match work, not job titles. A person can retain some actions while a robot performs others.",
"Count time, demand, dependencies, handoffs, and recovery. Action count alone cannot show staffing or cash savings.",
"Treat a product as a configuration: robot, tool, sensors, software, and interfaces.",
"Keep hard constraints separate from preferences. A known failure stays blocked. A missing value stays unknown.",
"Include the current method and manual process improvement. A valid recommendation can be stop or collect more data.",
"Use one case from opportunity through operation. The simulation is a service used by that case.",
"Use short sentences and stable terms. Explain units and missing data at the point of use."
])+p("Design terms: A task is a meaningful block of work. An action is a small observable step, such as scan or lift. A skill is behaviour under stated conditions. A capability is a measurable property that enables the behaviour. A work bundle is a set of actions that an actor can perform as a usable part of the process.")))
body.append(section("flow","2. Proposed application flow",'<div class="figure">'+main_svg()+'</div>'+p("Demand and supply join at action matching. A process option can use more than one technology and more than one person. Performance work can run in parallel to a draft evaluation. It must not silently convert an unknown result into a pass.")+p("The dashed feedback paths change the next case version. They do not overwrite the assumptions or evidence used for an earlier decision.")+f'<p><a href="application-flow.mmd">Download the editable Mermaid flow</a> · <a href="application-flow.svg">Open the full flow image</a></p>'))
body.append(section("navigation","3. Screen map and daily use",table(["Navigation","Purpose","Main actions"],[
    ("Executive", "See value, capacity, and exposure across sites.", "Filter; separate forecast/approved/observed benefit; open a case."),
    ("Evaluations", "Manage the initiative pipeline.", "Create case; assign owner; see stage, missing inputs, next decision, and expected range."),
    ("Deployments", "See robots and processes at each site.", "Filter planned/pilot/in service; open asset, release, process, performance, and issue records."),
    ("Shared libraries", "Reuse reviewed process templates, technologies, and source evidence.", "Add or revise a record; show where it is used; flag affected cases."),
    ("Case workspace", "Follow one clear journey.", "Overview → Inputs → Process → Matches → Scenarios → Results → Deployment → Learning."),
])+p("Keep the site, process, case version, data status, and next action visible in the case header. Show one main work area. Put detailed source records in a side panel. Use table, process map, and layout as views of the same case. Do not create a second journey for AMRs or a separate main mode for the twin.")+p("Proposed first visit: open Evaluations, create a tote case, add a process source, review the action breakdown, confirm the human baseline, and inspect the match matrix. A small guided example can explain each action without adding another product mode.")))
body.append(section("inputs","4. Input contract",p("The form must adapt to the process and decision. Not every site will have every file. Permit drafts, name missing data, and state what the missing data prevents. The workshop also makes this point: input needs differ by site and process [S3].")+table(["Input group","Fields and sources","Use","Basis"],[[esc(c) for c in row] for row in inputs])+p("Every material value needs a unit, source, date/version, status, and validity conditions. Optional fields include sample count, range/distribution, method, and reviewer. Use these statuses: Sample, Assumed, Supplier claim, Simulated, Measured, Verified for stated conditions, Unknown, and Out of date. A reviewed claim is still a claim until evidence supports a stronger status.")))
body.append(section("logic","5. Matching, process design, and fleet logic",li([
"Build a baseline action graph. Record sequence, alternatives, repeat counts, and resources used at the same time.",
"Map action needs to skills and measurable capability limits. Test load, grip, reach, path, sensing, quality, tool, interface, and operating conditions as relevant.",
"Check each complete configuration. Return supported, blocked, unknown, or not assessed, with the reason and evidence. Supported by a claim is not proven at this site.",
"Form usable action bundles. A lift/carry/place sequence can require one actor to retain load control. Splitting it can add tooling, handoffs, or an invalid method.",
"Design current, improved manual, assisted, hybrid, and automated options where applicable. Show who performs every action and each recovery duty.",
"Search a bounded set of compatible configurations, robot counts, human roles, and shift plans. State search limits and exclusions. Do not claim a global optimum from a small sample.",
"Evaluate completed good units against the same demand and quality targets. Include charge and downtime definitions, shared chargers, queues, handoffs, buffers, and support work to the extent the selected model supports them.",
"If a simple model cannot represent an important shared resource or queue, show the limit and request a process evaluation. Do not make the local calculator appear to be a discrete-event or physics simulation."
])+p("For sequential actions, active work hours can start from demand × action frequency × active seconds / 3,600, summed by actor. Parallel actions and shared duties need explicit resource logic. Elapsed process time is not always the sum of all action times.")+p("A simple fleet bound is required robot busy hours divided by usable robot hours, rounded up. This is only an initial capacity check. It cannot prove peak service, charger capacity, traffic performance, resilience, or the final staffing plan.")+p("Example: a humanoid may handle 5 of 12 actions. Those actions might represent a small or large share of human work time. A person may still need to be present for scanning, recovery, or another critical action. The result must show action count, work-time change, staffing change, and cash benefit as separate fields.")))
body.append(section("economics","6. Business-case logic and outputs",p("The EUR75,000 annual human cost, EUR100,000 robot price, and 40% coverage in the request are examples. They do not determine the robot count or savings. The 5,000-tote rate also needs a clear denominator: person or team, and shift or day.")+table(["Step","Required calculation or record"],[
("Baseline", "Use confirmed output, people by shift, paid/productive hours, current method, and current total cost."),
("Work change", "Calculate human work that remains. Add supervision, handoff, recovery, replenishment, and charge duties. Show bottlenecks and unusable time fragments."),
("Staffing change", "Use an achievable shift plan, minimum coverage, breaks, peaks, and shared roles. Show avoided hires, cash labour reduction, and redeployed capacity separately."),
("Technology cost", "Include purchased units or recurring lease/RaaS, tools, integration, site changes, compute, software, energy, support, maintenance, spares, training, commissioning, and ramp-up. State inclusions."),
("Retained benefit", "State the viewpoint and contract. Separate benefit passed to the customer from DP World retained benefit. Allocate each cost to its actual payer."),
("Cash flow", "Net annual cash saving = captured annual cash benefit minus added annual cash cost. Include upfront and ramp-up cash flows by period. Do not charge purchase cash and depreciation twice."),
("Payback", "Find the first period in which cumulative incremental cash flow becomes non-negative. Upfront cost / steady annual net cash saving is only a simple no-ramp estimate. If savings are non-positive, show no payback."),
("Other measures", "Show life-cycle cost, cost per completed good unit, and optional NPV with an agreed rate. If ROI is shown, state its formula and period. A two-year return of investment is payback, not an ROI percentage."),
("Sensitivity", "Show low/base/high assumptions and break-even throughput, robot price, intervention rate, and cash benefit capture where useful. Do not call scenario ranges probabilities."),
])+p("A recommendation should read like this: For [site/process and demand], option [ID/version] assigns [actions] to [configuration and count] and retains [roles/staff plan]. It meets [requirements] under [conditions]. Expected annual net cash saving is [range/status]. Payback is [period/status]. Missing evidence is [list]. Next action is [benchmark, pilot, change, or stop]. Unknown fields must remain unknown.")+p("Separate two business questions: Does this automation change create value? What extra value does this platform create compared with the existing engineering and delivery method? The platform cannot claim all robot savings as its own added benefit.")))
body.append(section("evidence","7. Performance evidence and confidence",p("Keep the datasheet-versus-first-simulation question open. The workshop contains competing views [S4]. A datasheet can provide a value and its stated conditions. It does not by itself prove the duration, error rate, or recovery cost of a new site task. A simulation result also needs input validity and a check against reality. AWS must define a suitable evidence plan for this PoC.")+table(["Result shown in the product","Meaning","Display rule"],[
("Capability fit", "Does the configuration meet the stated action requirements?", "Show each requirement, value, source, conditions, and supported/blocked/unknown status."),
("Performance evidence", "What supports the time, success, failure, and recovery estimates?", "Show supplier claim, assumption, simulation, benchmark, or field observation. Include version, sample, and transfer limits."),
("Economic robustness", "Does the case remain useful under agreed adverse assumptions?", "Show the break-even values and scenario results. A share of passing scenarios is not automatically a probability."),
("Deployment readiness", "Are the required site, interface, release, support, and test items complete?", "Show required items and open issues. Keep demo review separate from real authority."),
("Probability, when supported", "Chance of a defined event under stated conditions and a defined time window.", "Leave unavailable until the event, data/model, validation, calibration, and uncertainty method are agreed."),
])+p("A statement such as 55% confidence is incomplete. It could mean a 55% chance of one successful grasp, meeting shift output, or making a positive business case. These are different events. Do not merge them into one score. A measured success-rate estimate can have statistical uncertainty, but its validity still depends on the sample and operating conditions.")+p("For version 2, use clear source labels, explicit gaps, conditional results, and scenario ranges. Add a quantitative probability only when there is a defensible method. A financial improvement must never increase the displayed quality of technical evidence.")))
body.append(section("deployment","8. Deployment, pilot, and improvement",'<div class="figure">'+deployment_svg()+'</div>'+p("Deployment starts from the selected scenario. It is a shared module across technology types. It includes site preparation, interfaces, an execution route, release records, tests, pilot planning, observations, and support. It may include model or policy training where the selected hardware and task require it.")+p("AWS and the OEM must explain the actual humanoid stack. The platform must not assume that it will create a robot brain from scratch. Some solutions use OEM configuration and commissioning. Others need model adaptation, control work, simulation, demonstration data, or training. The deployment plan must name each dependency and its owner.")+p("The platform coordinates planning, records, service requests, and decisions. Real-time machine control, safe motion, and the vendor fleet controller remain separate technical boundaries unless a later design explicitly assigns that role.")+p("The improvement loop is controlled: collect trial data, check its quality, compare with the baseline, revise the affected records, test the change, and review a new release. Do not automatically retrain or load hardware after each new observation.")+f'<p><a href="deployment-flow.mmd">Download the deployment flow</a> · <a href="deployment-flow.svg">Open the deployment flow image</a></p>'))
body.append(section("reuse","9. What to reuse from Humanoid",p("Review basis: local source files, product rules, process-editor code, matching code, AMR lifecycle code, twin client/adapters, and the saved AMR economics image. I also read the referenced task. This was a design review; I did not run the reference application, backend, training, or hardware integration. Historical review results are not new test results.")+table(["Area","Reuse","Change before use in version 2","Evidence"],[
("Process records", "Hierarchy, observable actions, evidence links, skill/capability distinction, exceptions, and timing method.", "Use progressive entry. Avoid forcing every hierarchy level into the first form.", "H1, H2"),
("Change control", "Input revisions, source links, historical decision snapshots, and invalidation after material edits.", "Use durable local cases and mark every affected result. Extend beyond session-only editor state.", "H2"),
("Hard checks", "Payload, reach, clearance, and other explicit comparisons with reasons.", "Use blocked/unknown/invalid distinctly. Do not use arbitrary 1–10 skill scores as validated physics.", "H3, H4"),
("Partial work", "Building-block views and capability explanations.", "Replace full-task FTE attribution. Build the hybrid process and calculate retained work and staffing.", "H3"),
("AMR planning", "Fleet, charge, exception recovery, benefit retention, commercial model, and ten-stage delivery concept.", "Move these into the common case workflow. Derive released work from the action plan instead of an entered release percentage. Recheck all formulas for the new cost perspective.", "H4"),
("Learning and brief", "Observed data entry, plan reviews, readiness gaps, export, and restore concepts.", "Do not import past computed results as current authority. Keep demo and field records separate.", "H4"),
("Navigation", "Useful individual tools: process editor, site view, library, scenario view, and delivery steps.", "Replace the mode switches and overlapping Profiler journeys with three dashboards and one case journey.", "H5"),
("Twin API", "Separate service client and normalized data contracts.", "Do not copy the reference API as proof of robotics training or deployment. Missing values must not silently become valid zeroes.", "H6"),
])+p("The current Hybrid Workforce model also needs replacement at its calculation boundary [V1]. Its process-level score, assumed residual labour, and economics-based confidence cannot support the new action-level, mixed-team workflow. Reusing its visual cards without changing that logic would preserve the main error.")))
body.append(section("functions",f"10. Function list ({len(features)} items)",p("This is the intended coverage of the version 2 mockup. Working means a local function that we propose to build after validation. It does not mean the function exists now. External robotics functions stay visible as clear planning or integration screens.")+''.join('<details open><summary>'+esc(g)+'</summary>'+table(["ID / function","Required behaviour","Version 2 mode","Acceptance check"],[[f'<strong>{f["id"]} · {esc(f["feature"])}</strong>',esc(f['behavior']),esc(f['v2_mode']),esc(f['acceptance_check'])] for f in features if f['group']==g])+'</details>' for g in dict.fromkeys(f['group'] for f in features))+f'<p><a href="feature-list.csv">Download the function list</a></p>'))
body.append(section("build","11. Rebuild sequence after validation",table(["Stage","Visible result","Check before the next stage"],[
("1. Case and baseline", "New navigation, local case storage, input register, process editor, and a reviewed tote example.", "Edit a task and reload. Units and unknown data remain correct. Reconcile baseline work, output, and staff."),
("2. Matching and process options", "Configuration library, action matrix, work bundles, and mixed human/robot process design.", "A hard constraint blocks the option. Partial coverage leaves explicit human work. A configuration change marks results out of date."),
("3. Evaluation and economics", "Bounded fleet search, simple capacity model, cash-flow calculation, sensitivity, and recommendation report.", "Check a known hand calculation. Test zero demand, missing time, negative economics, charge/downtime overlap, and a case where human coverage prevents cash savings."),
("4. Delivery and learning", "Deployment plan, configuration/training route, release record, pilot plan, assets, and observed results.", "Carry the selected version into delivery. Keep planned and observed data separate. A changed release requires new review."),
("5. Whole mockup review", "Three dashboards and a coherent path across every listed function.", "Walk the tote case through proceed, collect-data, and stop outcomes. Review desktop/mobile layout, keyboard use, report export, and controlled language."),
])+p("Do not give the rebuild a calendar promise before the design, backend scope, and input examples are agreed. Each stage must work through a complete user path. The visual mockup can be complete while external CAD, simulation, training, and hardware services remain unconnected.")+p("Proposed internal boundaries: case/source store; process model; configuration library; matching rules; scenario evaluator; economics; recommendation report; deployment records; observations; and replaceable external adapters. Use explicit input/output versions across these boundaries. Do not require microservices for the local mockup.")))
body.append(section("aws","12. Reset discussion with AWS",p("Use one working session to connect the tote PoC to this product flow. Ask the team to work from a concrete input case to a recommendation, then show the delivery path and its open dependencies. Do not measure progress only by whether a robot moves in a simulation.")+table(["Topic","Concrete output","Proposed lead"],[
("Product outcome", "One agreed process boundary, user journey, and report example. Mark what the PoC proves and what remains future work.", "Radoy and Rohit"),
("Performance evidence", "A decision on the missing task evidence, the first simulation question, alternatives, success measures, and reuse limits.", "AWS and site engineering"),
("Data contract", "One real input packet and an agreed task/configuration performance result format.", "Diego, site engineering, and AWS"),
("Recommendation engine", "A worked comparison of current work and bounded robot/team options, with retained human work and economics.", "Engineering, finance, and AWS"),
("Deployment route", "Named hardware, supported stack, owner duties, interfaces, test path, pilot path, and missing OEM access.", "AWS, OEM, and accountable integrator"),
("Scope and next demonstration", "A list of deliverables, exclusions, owners, evidence needed, and the next complete demonstration.", "Rohit and AWS delivery lead"),
])+p("The known source record does not prove that AWS still misunderstands the goal. It does show unresolved interfaces between the goal, performance work, recommendation logic, UI, and delivery [S4, S6]. Ask AWS to return the agreed flow and deliverables in its own words. Compare those outputs with the same case and acceptance checks.")))
question_html=''.join(f'<tr data-when="{esc(x["decision_time"])}"><td><strong>{x["id"]}</strong><br><small>{esc(x["group"])}</small></td><td>{esc(x["question"])}</td><td>{esc(x["proposed_default"])}</td><td>{esc(x["proposed_owner"])}</td><td><span class="tag">{esc(x["decision_time"])}</span></td></tr>' for x in questions)
filters=''.join(f'<option>{esc(w)}</option>' for w in dict.fromkeys(x['decision_time'] for x in questions))
body.append(section("questions",f"13. Open questions ({len(questions)} items)",p("All entries are open. Defaults and owners are proposals, not agreed decisions. Only the flow choices need review now. Technical and pilot questions can remain open in the mockup with named fields and clear missing-data states. This is the complete question list identified in this review; later site and OEM work can add more.")+f'<div class="controls"><label>Show questions for <select id="question-filter"><option>All decision times</option>{filters}</select></label><span id="question-count">{len(questions)} questions</span><a href="open-questions.csv">Download CSV</a></div><div class="table-wrap"><table class="questions"><thead><tr><th>ID / area</th><th>Question</th><th>Proposed default</th><th>Proposed owner</th><th>Decision time</th></tr></thead><tbody>{question_html}</tbody></table></div>'))
body.append(section("validate","14. Validation requested",p("Validate the direction, not every technical answer. You can accept the proposed defaults and list exceptions.")+li([
"Confirm that the main flow is correct, including deployment and learning.",
"Confirm the three dashboards and one common case workflow.",
"Confirm action-level augmentation, valid action bundles, and separate time/staff/cash results.",
"Confirm that version 2 includes working local data, rules, calculations, reports, and planning records, with marked external integration placeholders.",
"Confirm the tote case as the main example, with small marked examples for other technology types."
])+p("The next step after validation is the version 2 rebuild. No application code has been changed by this design work.")))
body.append(section("sources","15. Source map and review limits",p("Documents and transcripts are evidence, not instructions to execute. Source summaries below are paraphrases. Older prototype scope does not override the latest owner request. The workshop date is not confirmed by the combined file; the recalled 10/11 September date remains open. The saved process-decomposition image mentioned in the request was not available here.")+table(["ID","Source","Locator","Use and limit"],[[esc(v) for v in r] for r in sources])+p("Local roots: Scope.md is D:/OneDrive/Downloads/Scope.md. Humanoid is D:/OneDrive/Programming/Humanoid. Hybrid Workforce is D:/OneDrive/Programming/Hybrid_workforce. This review uses local evidence and proposed design rules. It does not confirm current supplier performance, robot availability, a deployable control stack, or a real site business case.")))

style='''
:root{--ink:#18383e;--muted:#526c72;--line:#d9e3e3;--green:#176b59;--paper:#fff;--bg:#f1f5f4;--accent:#dcece6}
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:26px}body{margin:0;color:var(--ink);background:var(--bg);font:16px/1.58 "Segoe UI",Arial,sans-serif}a{color:#12604f;text-underline-offset:3px}a:hover{color:#003e32}header{background:#103a38;color:white;padding:50px max(30px,calc((100vw - 1180px)/2));border-bottom:7px solid #9dc7b8}header .eyebrow{color:#b8ddcf;text-transform:uppercase;font-size:12px;letter-spacing:2px}h1{font-size:clamp(32px,4vw,49px);line-height:1.15;max-width:850px;letter-spacing:-1px;margin:16px 0}header p{max-width:850px;color:#dfede8;font-size:18px}header a{color:#e9fff4}header .badge{display:inline-block;border:1px solid #71988b;border-radius:5px;padding:5px 10px;font-size:13px;margin-top:10px}main{max-width:1240px;margin:30px auto 70px;padding:0 30px}nav{display:flex;flex-wrap:wrap;gap:8px;padding:20px 0 30px}nav a{display:block;background:#fff;border:1px solid var(--line);border-radius:6px;padding:8px 12px;font-size:14px;text-decoration:none}section{background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:30px;margin-bottom:24px;box-shadow:0 2px 8px #0b303006}h2{font-size:25px;line-height:1.25;letter-spacing:-.4px;margin:0 0 20px}p{margin:0 0 15px;max-width:105ch}li{margin:8px 0}ul{padding-left:24px}p:last-child{margin-bottom:0}.table-wrap{overflow-x:auto;margin:20px 0 12px}table{width:100%;border-collapse:collapse;font-size:14px;line-height:1.5}th{text-align:left;vertical-align:top;background:#edf3f1;color:#173e36;font-size:12px;letter-spacing:.35px;padding:13px 12px;border-bottom:2px solid #cadbd3}td{padding:14px 12px;border-bottom:1px solid #e1e9e6;vertical-align:top;min-width:110px}td:first-child{font-weight:600;min-width:125px}tr:last-child td{border-bottom:0}.figure{border:1px solid #e0e7e5;border-radius:9px;background:#f8faf9;padding:10px}.figure svg{display:block;width:100%;height:auto}details{border:1px solid var(--line);border-radius:7px;margin:12px 0}summary{cursor:pointer;font-weight:650;padding:15px;background:#f1f6f3}details .table-wrap{margin:0}small{font-size:12px;font-weight:400;color:var(--muted)}.tag{display:inline-block;background:#e6f0eb;border-radius:4px;padding:4px 6px;font-size:12px;line-height:1.4}.controls{display:flex;gap:20px;align-items:center;flex-wrap:wrap;padding:14px 0}select{font:inherit;border:1px solid #a7bcb3;border-radius:5px;padding:7px 10px;background:white;color:var(--ink)}#question-count{color:var(--muted);font-size:14px}.questions{min-width:980px}.questions td:nth-child(2){width:23%}.questions td:nth-child(3){width:40%}footer{max-width:1180px;margin:0 auto 40px;padding:0 30px;font-size:13px;color:var(--muted)}@media(max-width:700px){main{padding:0 12px;margin-top:12px}header{padding:30px 22px}section{padding:20px 16px}nav{gap:5px;padding:10px 0 18px}nav a{font-size:12px;padding:6px 8px}h2{font-size:22px}td,th{padding:10px}.figure{overflow-x:auto}.figure svg{min-width:740px}body{font-size:15px}}@media print{body{background:white;font-size:10pt}header{padding:20px;color:#18383e;background:white;border-bottom:2px solid #18383e}header p,header .eyebrow{color:#18383e}h1{font-size:30pt}header .badge{color:#18383e}nav,.controls{display:none}main{padding:0;margin:16px 0;max-width:none}section{border:0;box-shadow:none;padding:10px 0;break-before:page}h2{font-size:18pt}.figure{padding:0;border:0}table{font-size:8pt}tr{break-inside:avoid}.table-wrap{overflow:visible}.questions{min-width:0}details{border:0}summary{padding:8px 0}a{color:inherit}footer{padding:0}.figure svg{min-width:0}}
'''
nav=[("mandate","Goal"),("flow","Application flow"),("navigation","Screens"),("inputs","Inputs"),("logic","Matching"),("economics","Economics"),("evidence","Confidence"),("deployment","Deployment"),("reuse","Humanoid review"),("functions","Functions"),("build","Build plan"),("aws","AWS reset"),("questions","Questions"),("validate","Validate"),("sources","Sources")]
script='''const select=document.getElementById('question-filter');const rows=[...document.querySelectorAll('.questions tbody tr')];select.addEventListener('change',()=>{let count=0;for(const row of rows){row.hidden=select.value!=='All decision times'&&row.dataset.when!==select.value;if(!row.hidden)count++;}document.getElementById('question-count').textContent=count+' questions';});'''
document='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hybrid Workforce — version 2 design review</title><style>'+style+'</style></head><body><header><div class="eyebrow">Hybrid Workforce Platform · Design review · 18 October 2026</div><h1>From work steps to a hybrid team in the warehouse</h1><p>Define the work. Match the technology. Check performance and cost. Prepare deployment. Improve with field evidence.</p><span class="badge">Proposed flow · Awaiting owner validation · Application unchanged</span></header><main><nav aria-label="Design review contents">'+''.join(f'<a href="#{i}">{esc(t)}</a>' for i,t in nav)+'</nav>'+''.join(body)+'</main><footer>Version 2 design proposal. All numerical examples are illustrative. Open this HTML file directly, or use the Codex preview. No external network resources are required.</footer><script>'+script+'</script></body></html>'

ROOT.mkdir(parents=True, exist_ok=True)
(ROOT/'design-review.html').write_text(document,encoding='utf-8')
(ROOT/'application-flow.mmd').write_text(main_mermaid,encoding='utf-8')
(ROOT/'deployment-flow.mmd').write_text(deployment_mermaid,encoding='utf-8')
(ROOT/'application-flow.svg').write_text(main_svg(),encoding='utf-8')
(ROOT/'deployment-flow.svg').write_text(deployment_svg(),encoding='utf-8')
for name,rows in [('open-questions.csv',questions),('feature-list.csv',features)]:
    with (ROOT/name).open('w',encoding='utf-8-sig',newline='') as f:
        writer=csv.DictWriter(f,fieldnames=list(rows[0]))
        writer.writeheader();writer.writerows(rows)
